mapper.select:


    b.del_flag = '0'
    and (
        b.batch_status = '7'
        or ifnull(b.total_paid_amount, 0) < ifnull(b.total_payable_amount, 0)
        or ifnull(b.account_received_amount, 0) < ifnull(b.total_payable_amount, 0)
    )

        and b.batch_no like concat('%', #{batchNo}, '%')


        and b.stat_month = #{statMonth}


        and b.dispatch_enterprise_id = #{dispatchEnterpriseId}


        and ifnull(h.handle_status, 'pending') = #{handleStatus}


        and b.region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}
    ${params.enterpriseDataScope}

order by overdue_days desc, arrears_amount desc, b.batch_id desc

select count(distinct b.dispatch_enterprise_id) from t_salary_batch b where b.del_flag = '0' and ( b.batch_status = '7' or ifnull(b.total_paid_amount, 0) < ifnull(b.total_payable_amount, 0) or ifnull(b.account_received_amount, 0) < ifnull(b.total_payable_amount, 0) )
and b.stat_month = #{statMonth}
and b.region_code like concat(#{regionCode}, '%')
